  app.post('/api/procurement/receipts',auth,need('procurement.receive'),async(req,res)=>{const b=req.body||{};if(!b.purchaseOrderId||!b.locationId) return res.status(400).json({error:'Purchase order and inventory location are required'});try{const client=await pool.connect();try{await client.query('BEGIN');const po=(await client.query("SELECT * FROM purchase_orders WHERE id=$1 AND status IN ('Approved','Partially Received') FOR UPDATE",[b.purchaseOrderId])).rows[0];if(!po)throw new Error('Purchase order is not approved or has no remaining receivable quantity');const pol=(await client.query(`SELECT l.*,v.sku,v.serialized,v.cost_price FROM purchase_order_lines l JOIN product_variants v ON v.id=l.variant_id WHERE l.purchase_order_id=$1 ORDER BY l.id`,[po.id])).rows;const gr=(await client.query('INSERT INTO goods_receipts(grn_no,purchase_order_id,location_id,supplier_delivery_note,status,notes,received_by,received_at) VALUES($1,$2,$3,$4,\'Draft\',$5,$6,now()) RETURNING *',[procurementNo('GRN'),po.id,b.locationId,text(b.supplierDeliveryNote),text(b.notes),req.user.id])).rows[0];let totalReceived=0;for(const l of parseLines(b.lines)){const line=pol.find(x=>x.id===l.purchaseOrderLineId);if(!line)throw new Error('Purchase order line not found');const qty=money(l.receivedQty);const already=money(line.received_qty);if(!(qty>0)||already+qty>money(line.quantity)+1e-9)throw new Error(`Receipt exceeds ordered quantity for ${line.sku}`);const rejected=Math.max(0,money(l.rejectedQty));if(rejected>=qty)throw new Error('Rejected quantity must be less than received quantity');const serials=jsonArray(l.serials);if(line.serialized&&(!Number.isInteger(qty)||serials.length!==qty))throw new Error(`Serialized SKU ${line.sku} requires exactly ${qty} serial/IMEI records`);await client.query('INSERT INTO goods_receipt_lines(goods_receipt_id,purchase_order_line_id,variant_id,ordered_qty,received_qty,rejected_qty,unit_cost,serials,notes) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9)',[gr.id,line.id,line.variant_id,line.quantity,qty,rejected,money(l.unitCost)||money(line.unit_price),JSON.stringify(serials),text(l.notes)]);await changeStock(client,{variantId:line.variant_id,locationId:b.locationId,delta:qty-rejected,type:'RECEIPT',actorId:req.user.id,referenceType:'GoodsReceipt',referenceId:gr.id,reason:`Goods receipt ${gr.grn_no}`,unitCost:money(l.unitCost)||money(line.unit_price)});for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;await client.query('INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,\'In Stock\',$6,now())',[line.variant_id,b.locationId,x.serialNumber||null,x.imei1||null,x.imei2||null,money(l.unitCost)||money(line.unit_price)])}await client.query('UPDATE purchase_order_lines SET received_qty=received_qty+$1 WHERE id=$2',[qty,line.id]);totalReceived+=qty-rejected}const outstanding=(await client.query('SELECT count(*)::int c FROM purchase_order_lines WHERE purchase_order_id=$1 AND received_qty<quantity',[po.id])).rows[0].c;const status=outstanding===0?'Received':'Partially Received';const done=(await client.query("UPDATE goods_receipts SET status='Posted' WHERE id=$1 RETURNING *",[gr.id])).rows[0];await client.query('UPDATE purchase_orders SET status=$1,updated_at=now() WHERE id=$2',[status,po.id]);if(status==='Partially Received'){const outstandingLines=(await client.query('SELECT id,quantity,received_qty FROM purchase_order_lines WHERE purchase_order_id=$1 AND received_qty<quantity',[po.id])).rows;for(const ol of outstandingLines){const open=(await client.query("SELECT id FROM purchase_order_backorders WHERE purchase_order_line_id=$1 AND status='Open'",[ol.id])).rows[0];const qty=money(ol.quantity)-money(ol.received_qty);if(open)await client.query('UPDATE purchase_order_backorders SET quantity=$1 WHERE id=$2',[qty,open.id]);else await client.query('INSERT INTO purchase_order_backorders(purchase_order_line_id,quantity,notes,created_by) VALUES($1,$2,$3,$4)',[ol.id,qty,'Auto-created from partial goods receipt',req.user.id]);}}const legacyReceipt=(await client.query('INSERT INTO stock_receipts(receipt_no,location_id,supplier_name,supplier_reference,notes,created_by,purchase_order_id,supplier_id,goods_receipt_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9) RETURNING id',[done.grn_no,b.locationId,(await client.query('SELECT legal_name FROM suppliers WHERE id=$1',[po.supplier_id])).rows[0].legal_name,text(b.supplierDeliveryNote),text(b.notes),req.user.id,po.id,po.supplier_id,done.id])).rows[0];for(const gl of (await client.query('SELECT * FROM goods_receipt_lines WHERE goods_receipt_id=$1',[done.id])).rows){await client.query('INSERT INTO stock_receipt_lines(receipt_id,variant_id,quantity,unit_cost,serials) VALUES($1,$2,$3,$4,$5)',[legacyReceipt.id,gl.variant_id,gl.received_qty,gl.unit_cost,gl.serials])}await client.query('COMMIT');await audit(req.user,'GOODS_RECEIPT_POSTED','GoodsReceipt',done.id,`Posted ${done.grn_no}; received ${totalReceived} units`,null,done,req.req);res.status(201).json(done)}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}}catch(e){res.status(400).json({error:e.message})}});

  app.patch('/api/procurement/receipts/:id/cancel',auth,need('procurement.receive'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const gr=(await client.query("SELECT * FROM goods_receipts WHERE id=$1 AND status='Posted' FOR UPDATE",[req.params.id])).rows[0];if(!gr)throw new Error('Posted goods receipt not found');const lines=(await client.query('SELECT gl.*,pol.quantity ordered_qty,pol.received_qty current_received,v.serialized,v.sku FROM goods_receipt_lines gl JOIN purchase_order_lines pol ON pol.id=gl.purchase_order_line_id JOIN product_variants v ON v.id=gl.variant_id WHERE gl.goods_receipt_id=$1 FOR UPDATE',[gr.id])).rows;for(const l of lines){const qty=Number(l.received_qty)-Number(l.rejected_qty);if(qty<=0)continue;if(l.serialized){const serials=Array.isArray(l.serials)?l.serials:[];for(const sn of serials){const x=typeof sn==='string'?sn:(sn.serialNumber||sn.imei1||sn.imei2);const su=(await client.query("SELECT * FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$2 OR imei2=$2) FOR UPDATE",[l.variant_id,x])).rows[0];if(!su)throw new Error(`Serialized unit ${x||''} is missing`);if(su.status!=='In Stock'||String(su.location_id)!==String(gr.location_id))throw new Error(`Cannot reverse ${l.sku}: a serialized unit has already moved, been sold, reserved or serviced`);await client.query('DELETE FROM serialized_units WHERE id=$1',[su.id]);}}await changeStock(client,{variantId:l.variant_id,locationId:gr.location_id,delta:-qty,type:'RECEIPT_REVERSAL',actorId:req.user.id,referenceType:'GoodsReceipt',referenceId:gr.id,reason:`Reversal of goods receipt ${gr.grn_no}`,unitCost:l.unit_cost});await client.query('UPDATE purchase_order_lines SET received_qty=GREATEST(0,received_qty-$1) WHERE id=$2',[qty,l.purchase_order_line_id]);}await client.query("UPDATE goods_receipts SET status='Cancelled' WHERE id=$1",[gr.id]);const openPO=(await client.query("SELECT COUNT(*)::int c FROM purchase_order_lines WHERE purchase_order_id=$1 AND received_qty>0",gr.purchase_order_id)).rows[0].c;const hasOutstanding=(await client.query("SELECT COUNT(*)::int c FROM purchase_order_lines WHERE purchase_order_id=$1 AND received_qty<quantity",gr.purchase_order_id)).rows[0].c;const poStatus=openPO===0?'Approved':hasOutstanding?'Partially Received':'Received';await client.query('UPDATE purchase_orders SET status=$1,updated_at=now() WHERE id=$2',[poStatus,gr.purchase_order_id]);await client.query("UPDATE stock_receipts SET status='Cancelled' WHERE goods_receipt_id=$1",[gr.id]);await client.query('COMMIT');await audit(req.user,'GOODS_RECEIPT_REVERSED','GoodsReceipt',gr.id,`Reversed ${gr.grn_no}`,gr,{status:'Cancelled'},req.req);res.json({ok:true,status:'Cancelled'})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
  app.get('/api/procurement/invoices',auth,need('procurement.view'),async(req,res)=>res.json(await q(`SELECT i.*,s.legal_name supplier_name,po.po_no,COALESCE((SELECT sum(p.amount) FROM supplier_payments p WHERE p.invoice_id=i.id AND p.status='Completed'),0)::numeric paid_amount FROM supplier_invoices i JOIN suppliers s ON s.id=i.supplier_id LEFT JOIN purchase_orders po ON po.id=i.purchase_order_id ORDER BY i.created_at DESC LIMIT 300`)));
