  app.post('/api/procurement/payments',auth,need('procurement.payments'),async(req,res)=>{const b=req.body||{};if(!b.supplierId||!(money(b.amount)>0))return res.status(400).json({error:'Supplier and positive payment amount are required'});try{const client=await pool.connect();try{await client.query('BEGIN');if(b.invoiceId){const inv=(await client.query("SELECT * FROM supplier_invoices WHERE id=$1 AND supplier_id=$2 AND status IN ('Matched','Partially Paid') FOR UPDATE",[b.invoiceId,b.supplierId])).rows[0];if(!inv)throw new Error('Invoice is not payable');const paid=(await client.query("SELECT COALESCE(sum(amount),0) total FROM supplier_payments WHERE invoice_id=$1 AND status='Completed'",[inv.id])).rows[0].total;if(money(paid)+money(b.amount)>money(inv.total_amount)+0.01)throw new Error('Payment exceeds invoice balance');}const p=(await client.query('INSERT INTO supplier_payments(payment_no,supplier_id,invoice_id,amount,currency,payment_date,method,reference,status,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8,\'Completed\',$9,$10) RETURNING *',[procurementNo('PAY'),b.supplierId,b.invoiceId||null,money(b.amount),text(b.currency)||'UGX',b.paymentDate||new Date().toISOString().slice(0,10),text(b.method)||'Bank Transfer',text(b.reference),text(b.notes),req.user.id])).rows[0];if(b.invoiceId){await client.query('INSERT INTO supplier_payment_allocations(payment_id,invoice_id,amount) VALUES($1,$2,$3) ON CONFLICT DO NOTHING',[p.id,b.invoiceId,money(b.amount)]);const inv=(await client.query('SELECT total_amount FROM supplier_invoices WHERE id=$1',[b.invoiceId])).rows[0];const paid=(await client.query("SELECT COALESCE(sum(amount),0) total FROM supplier_payments WHERE invoice_id=$1 AND status='Completed'",[b.invoiceId])).rows[0].total;await client.query("UPDATE supplier_invoices SET status=$1,updated_at=now() WHERE id=$2",[money(paid)+0.01>=money(inv.total_amount)?'Paid':'Partially Paid',b.invoiceId])}await client.query('COMMIT');await audit(req.user,'SUPPLIER_PAYMENT_RECORDED','SupplierPayment',p.id,`Recorded payment ${p.payment_no}`,null,p,req.req);res.status(201).json(p)}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}}catch(e){res.status(400).json({error:e.message})}});

  app.post('/api/procurement/payments/:id/allocate',auth,need('procurement.payments'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const p=(await client.query("SELECT * FROM supplier_payments WHERE id=$1 AND status='Completed' FOR UPDATE",[req.params.id])).rows[0];if(!p)throw new Error('Completed supplier payment not found');const invoice=(await client.query("SELECT * FROM supplier_invoices WHERE id=$1 AND supplier_id=$2 AND status IN ('Matched','Partially Paid') FOR UPDATE",[req.body?.invoiceId,p.supplier_id])).rows[0];if(!invoice)throw new Error('Invoice is not payable for this supplier');const already=Number((await client.query('SELECT COALESCE(sum(amount),0) total FROM supplier_payment_allocations WHERE payment_id=$1',[p.id])).rows[0].total);const invoicePaid=Number((await client.query("SELECT COALESCE(sum(amount),0) total FROM supplier_payment_allocations WHERE invoice_id=$1",[invoice.id])).rows[0].total);const direct=Number((await client.query("SELECT COALESCE(sum(amount),0) total FROM supplier_payments WHERE invoice_id=$1 AND status='Completed' AND id<>$2",[invoice.id,p.id])).rows[0].total);const amount=Math.max(0,Number(req.body?.amount)||Number(p.amount)-already);if(amount<=0||already+amount>Number(p.amount)+0.01)throw new Error('Allocation exceeds payment amount');if(invoicePaid+direct+amount>Number(invoice.total_amount)+0.01)throw new Error('Allocation exceeds invoice balance');await client.query('INSERT INTO supplier_payment_allocations(payment_id,invoice_id,amount) VALUES($1,$2,$3) ON CONFLICT(payment_id,invoice_id) DO UPDATE SET amount=supplier_payment_allocations.amount+EXCLUDED.amount',[p.id,invoice.id,amount]);const totalPaid=Number((await client.query("SELECT COALESCE(sum(amount),0) total FROM supplier_payment_allocations WHERE invoice_id=$1",[invoice.id])).rows[0].total)+direct;await client.query("UPDATE supplier_invoices SET status=CASE WHEN $1>=total_amount-0.01 THEN 'Paid' ELSE 'Partially Paid' END,updated_at=now() WHERE id=$2",[totalPaid,invoice.id]);await client.query('COMMIT');const r=(await q('SELECT * FROM supplier_payment_allocations WHERE payment_id=$1 AND invoice_id=$2',[p.id,invoice.id]))[0];await audit(req.user,'SUPPLIER_PAYMENT_ALLOCATED','SupplierPayment',p.id,`Allocated payment to invoice ${invoice.invoice_no}`,null,r,req.req);res.status(201).json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
  app.get('/api/suppliers/:id/balance',auth,need('suppliers.view'),async(req,res)=>{const s=await supplierById(req.params.id);if(!s)return res.status(404).json({error:'Supplier not found'});const [invoiced,paid,overdue]=await Promise.all([q("SELECT COALESCE(sum(total_amount),0)::numeric total FROM supplier_invoices WHERE supplier_id=$1 AND status IN ('Matched','Partially Paid','Paid')",[s.id]),q("SELECT COALESCE(sum(amount),0)::numeric total FROM supplier_payments WHERE supplier_id=$1 AND status='Completed'",[s.id]),q("SELECT COALESCE(sum(total_amount-(SELECT COALESCE(sum(p.amount),0) FROM supplier_payments p WHERE p.invoice_id=i.id AND p.status='Completed')),0)::numeric total FROM supplier_invoices i WHERE i.supplier_id=$1 AND i.status IN ('Matched','Partially Paid') AND i.due_date<current_date",[s.id])]);res.json({invoiced:invoiced[0].total,paid:paid[0].total,balance:money(invoiced[0].total)-money(paid[0].total),overdue:overdue[0].total,currency:s.default_currency})});
