  async function approvalGuard(req,entityType,entity){
    const amount=entityType==='Requisition'?Number((await q('SELECT COALESCE(SUM(quantity*estimated_unit_cost),0) amount FROM purchase_requisition_lines WHERE requisition_id=$1',[entity.id]))[0].amount):entityType==='PurchaseOrder'?Number((await q('SELECT COALESCE(SUM(quantity*unit_price),0)+$2-$3+$4 amount FROM purchase_order_lines WHERE purchase_order_id=$1',[entity.id,entity.shipping_amount||0,entity.discount_amount||0,entity.tax_amount||0]))[0].amount):Number(entity.total_amount||0);
    const departmentId=entity.department_id||null;
    const rules=await q(`SELECT * FROM procurement_approval_rules WHERE entity_type=$1 AND active=true AND (department_id IS NULL OR department_id=$2) AND min_amount<= $3 AND (max_amount IS NULL OR max_amount>= $3) ORDER BY department_id NULLS LAST,min_amount DESC LIMIT 1`,[entityType,departmentId,amount]);
    if(rules.length && !req.permissions.has(rules[0].required_permission))throw new Error(`Approval requires permission ${rules[0].required_permission}`);
    if(entityType==='Requisition' && entity.needed_by && new Date(entity.needed_by)<new Date(new Date().toISOString().slice(0,10)))throw new Error('Requisition needed-by date is in the past');
    if(entityType==='Requisition'){
      const b=await q(`SELECT * FROM procurement_budgets WHERE active=true AND starts_on<=current_date AND ends_on>=current_date AND (department_id IS NULL OR department_id=$1) ORDER BY department_id NULLS LAST,starts_on DESC LIMIT 1`,[departmentId]);
      if(b.length){const committed=Number((await q(`SELECT COALESCE(SUM(l.quantity*l.unit_price),0) amount FROM purchase_orders po JOIN purchase_order_lines l ON l.purchase_order_id=po.id JOIN purchase_requisitions r ON r.id=po.requisition_id WHERE po.status<>'Cancelled' AND r.department_id IS NOT DISTINCT FROM $1 AND po.created_at::date BETWEEN $2 AND $3`,[departmentId,b[0].starts_on,b[0].ends_on]))[0].amount);if(committed+amount>Number(b[0].amount)+0.01)throw new Error('Approval would exceed the active procurement budget');}
    }
  }

  async function transitionRequisition(req,res,status){const allowed=status==='Approved'?['Submitted']:status==='Rejected'?['Submitted']:['Draft','Submitted','Approved'];const old=(await q(`SELECT * FROM purchase_requisitions WHERE id=$1 AND status = ANY($2)`,[req.params.id,allowed]))[0];if(!old)return res.status(404).json({error:`Requisition cannot be ${status.toLowerCase()} from its current state`});if(status==='Approved'&&old.requester_id===req.user.id)return res.status(400).json({error:'The requester cannot approve their own requisition'});if(status==='Approved'){try{await approvalGuard(req,'Requisition',old)}catch(e){return res.status(400).json({error:e.message})}}const field=status==='Approved'?'approved_at':status==='Rejected'?'rejected_at':'cancelled_at';const r=(await q(`UPDATE purchase_requisitions SET status=$1,${field}=now(),updated_at=now() WHERE id=$2 RETURNING *`,[status,old.id]))[0];await pool.query('INSERT INTO procurement_approvals(entity_type,entity_id,action,actor_id,comments) VALUES($1,$2,$3,$4,$5)',['Requisition',r.id,status,req.user.id,text(req.body?.comments)]);await audit(req.user,`REQUISITION_${status.toUpperCase()}`,'Requisition',r.id,`${status} ${r.requisition_no}`,old,r,req.req);res.json(r)}
  app.patch('/api/procurement/requisitions/:id/reopen',auth,need('procurement.requisition'),async(req,res)=>{const old=(await q("SELECT * FROM purchase_requisitions WHERE id=$1 AND status='Rejected'",[req.params.id]))[0];if(!old)return res.status(404).json({error:'Rejected requisition not found'});const r=(await q("UPDATE purchase_requisitions SET status='Draft',rejected_at=NULL,updated_at=now() WHERE id=$1 RETURNING *",[old.id]))[0];await audit(req.user,'REQUISITION_REOPENED','Requisition',r.id,`Reopened ${r.requisition_no}`,old,r,req.req);res.json(r)});
  async function transitionPO(req,res,status){const allowed=status==='Submitted'?['Draft']:status==='Approved'?['Submitted']:['Draft','Submitted','Approved','Partially Received'];const old=(await q(`SELECT * FROM purchase_orders WHERE id=$1 AND status = ANY($2)`,[req.params.id,allowed]))[0];if(!old)return res.status(404).json({error:`Purchase order cannot be ${status.toLowerCase()} from its current state`});if(status==='Approved'&&old.created_by===req.user.id)return res.status(400).json({error:'The purchase order creator cannot approve their own purchase order'});if(status==='Approved'){try{await approvalGuard(req,'PurchaseOrder',old)}catch(e){return res.status(400).json({error:e.message})}}let r;if(status==='Approved'){r=(await q("UPDATE purchase_orders SET status='Approved',approved_at=now(),approved_by=$1,updated_at=now() WHERE id=$2 RETURNING *",[req.user.id,old.id]))[0]}else if(status==='Submitted'){r=(await q("UPDATE purchase_orders SET status='Submitted',submitted_at=now(),updated_at=now() WHERE id=$1 RETURNING *",[old.id]))[0]}else{r=(await q("UPDATE purchase_orders SET status=$1,updated_at=now() WHERE id=$2 RETURNING *",[status,old.id]))[0]}await pool.query('INSERT INTO procurement_approvals(entity_type,entity_id,action,actor_id,comments) VALUES($1,$2,$3,$4,$5)',['PurchaseOrder',r.id,status,req.user.id,text(req.body?.comments)]);await audit(req.user,`PURCHASE_ORDER_${status.toUpperCase().replaceAll(' ','_')}`,'PurchaseOrder',r.id,`${status} ${r.po_no}`,old,r,req.req);res.json(r)}
