  app.get('/api/procurement/budgets',auth,need('procurement.view'),async(req,res)=>res.json(await q(`SELECT b.*,d.name department_name,COALESCE((SELECT SUM(CASE WHEN po.status NOT IN ('Cancelled') THEN l.quantity*l.unit_price ELSE 0 END) FROM purchase_orders po JOIN purchase_order_lines l ON l.purchase_order_id=po.id JOIN purchase_requisitions r ON r.id=po.requisition_id WHERE (b.department_id IS NULL OR r.department_id=b.department_id) AND po.created_at::date BETWEEN b.starts_on AND b.ends_on),0)::numeric committed FROM procurement_budgets b LEFT JOIN departments d ON d.id=b.department_id ORDER BY b.starts_on DESC`)));
