  app.post('/api/procurement/orders/:id/revise',auth,need('procurement.manage'),async(req,res)=>{
    const client=await pool.connect();try{await client.query('BEGIN');const po=(await client.query('SELECT * FROM purchase_orders WHERE id=$1 FOR UPDATE',[req.params.id])).rows[0];if(!po)throw new Error('Purchase order not found');if(['Received','Cancelled'].includes(po.status))throw new Error('Received or cancelled purchase orders cannot be revised');const lines=(await client.query('SELECT * FROM purchase_order_lines WHERE purchase_order_id=$1 ORDER BY id',[po.id])).rows;const revNo=Number((await client.query('SELECT COALESCE(MAX(revision_number),0)+1 n FROM purchase_order_revisions WHERE purchase_order_id=$1',[po.id])).rows[0].n);const snapshot={purchaseOrder:po,lines};const rev=(await client.query('INSERT INTO purchase_order_revisions(purchase_order_id,revision_number,reason,snapshot,created_by) VALUES($1,$2,$3,$4,$5) RETURNING *',[po.id,revNo,text(req.body?.reason)||'Manual procurement revision',JSON.stringify(snapshot),req.user.id])).rows[0];if(['Approved','Submitted','Partially Received'].includes(po.status))await client.query("UPDATE purchase_orders SET status='Draft',updated_at=now() WHERE id=$1",[po.id]);await client.query('COMMIT');await audit(req.user,'PURCHASE_ORDER_REVISED','PurchaseOrder',po.id,`Created revision ${revNo}`,po,rev,req.req);res.status(201).json(rev)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}
  });
