  app.post('/api/procurement/orders/:id/backorders',auth,need('procurement.manage'),async(req,res)=>{const b=req.body||{};const line=(await q('SELECT l.*,po.status FROM purchase_order_lines l JOIN purchase_orders po ON po.id=l.purchase_order_id WHERE l.id=$1 AND po.id=$2',[b.purchaseOrderLineId,req.params.id]))[0];if(!line)return res.status(404).json({error:'Purchase order line not found'});const outstanding=money(line.quantity)-money(line.received_qty);const qty=money(b.quantity)||outstanding;if(!(qty>0)||qty>outstanding+0.01)return res.status(400).json({error:'Backorder quantity exceeds outstanding quantity'});const r=(await q('INSERT INTO purchase_order_backorders(purchase_order_line_id,quantity,notes,created_by) VALUES($1,$2,$3,$4) RETURNING *',[line.id,qty,text(b.notes),req.user.id]))[0];await audit(req.user,'PURCHASE_ORDER_BACKORDER_CREATED','PurchaseOrder',req.params.id,`Created backorder ${qty}`,null,r,req.req);res.status(201).json(r)});
