  app.get('/api/procurement/control-center',auth,need('procurement.view'),async(req,res)=>{const [readiness,analytics,rules,budgets]=await Promise.all([q(`SELECT (SELECT count(*)::int FROM supplier_documents WHERE expires_at IS NOT NULL AND expires_at<=current_date+30) expiring_supplier_documents,(SELECT count(*)::int FROM suppliers WHERE status='Active' AND qualification_status<>'Approved') active_unqualified_suppliers,(SELECT count(*)::int FROM procurement_invoice_match_exceptions WHERE status='Open') open_invoice_exceptions,(SELECT count(*)::int FROM supplier_invoices WHERE status IN ('Matched','Partially Paid') AND due_date<current_date) overdue_invoices,(SELECT count(*)::int FROM purchase_orders WHERE status='Partially Received') partially_received_orders`),q(`SELECT s.id,s.legal_name,COUNT(DISTINCT po.id)::int purchase_orders,COALESCE(SUM(l.quantity*l.unit_price),0)::numeric merchandise_value,COALESCE(SUM(l.received_qty*l.unit_price),0)::numeric received_value FROM suppliers s LEFT JOIN purchase_orders po ON po.supplier_id=s.id AND po.status<>'Cancelled' LEFT JOIN purchase_order_lines l ON l.purchase_order_id=po.id GROUP BY s.id,s.legal_name ORDER BY merchandise_value DESC LIMIT 20`),q(`SELECT * FROM procurement_approval_rules WHERE active=true ORDER BY entity_type,min_amount`),q(`SELECT * FROM procurement_budgets WHERE active=true ORDER BY starts_on DESC`)]);res.json({readiness:readiness[0],supplierSpend:analytics,rules,budgets});});
